function decodeEntities(value) {
  const named = { amp: '&', apos: "'", gt: '>', lt: '<', nbsp: ' ', quot: '"' };
  return value.replace(/&(#x[0-9a-f]+|#\d+|[a-z]+);/gi, (entity, reference) => {
    const lower = reference.toLowerCase();
    if (lower[0] !== '#') return named[lower] ?? entity;
    const codePoint = lower.startsWith('#x') ? Number.parseInt(lower.slice(2), 16) : Number.parseInt(lower.slice(1), 10);
    try { return String.fromCodePoint(codePoint); } catch { return entity; }
  });
}

function toPlainText(value) {
  return decodeEntities(value.replace(/<script[\s\S]*?<\/script>|<style[\s\S]*?<\/style>/gi, '').replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim());
}

function escapeMarkdown(value) { return value.replace(/([\\`*_{}[\]<>])/g, '\\$1'); }

function compact(value, maxLength) { return value.length <= maxLength ? value : `${value.slice(0, maxLength - 1).trimEnd()}…`; }

function requestIdFor(value) {
  let hash = 5381;
  for (const character of value) hash = ((hash << 5) + hash) ^ character.charCodeAt(0);
  return `proton-company-news-${(hash >>> 0).toString(36)}`;
}

function formatInBrisbane(date) {
  return new Intl.DateTimeFormat('en-AU', { timeZone: 'Australia/Brisbane', day: '2-digit', month: 'short', year: 'numeric' }).format(date);
}

function cloudinaryImageUrl(html) {
  const imageUrl = html.match(/<img\b[^>]*\bsrc=["']([^"']+)/i)?.[1] ?? '';
  try { return new URL(imageUrl).host === 'res.cloudinary.com' ? imageUrl : ''; } catch { return ''; }
}

return $input.all().flatMap((item) => {
  const post = item.json;
  // n8n's RSS reader exposes Proton's <category> elements in this array.
  // Matching the exact label avoids inferring product news from article titles.
  const categories = Array.isArray(post.categories) ? post.categories.map((category) => String(category).trim().toLowerCase()) : [];
  if (!categories.includes('company news')) return [];

  const postUrl = String(post.link ?? '').trim();
  const postId = String(post.guid ?? postUrl).trim();
  const title = String(post.title ?? '').trim();
  const description = compact(toPlainText(String(post.contentSnippet ?? post.description ?? post.content ?? '').trim()), 700);
  if (!postId || !postUrl || !title || !description) return [];

  const published = new Date(post.isoDate ?? post.pubDate ?? '');
  const publishedAt = Number.isNaN(published.valueOf()) ? null : published.toISOString();
  const publishedInBrisbane = publishedAt ? formatInBrisbane(published) : null;
  const imageUrl = cloudinaryImageUrl(String(post['content:encoded'] ?? post.content ?? ''));

  return [{
    json: {
      post_id: postId,
      title,
      description,
      post_url: postUrl,
      published_at: publishedAt,
      image_url: imageUrl,
      first_seen_at: new Date().toISOString(),
      message: [
        '🟣 **New Proton product news**',
        '',
        `**${escapeMarkdown(title)}**`,
        publishedInBrisbane ? `Published: ${publishedInBrisbane}` : null,
        '',
        escapeMarkdown(description),
        '',
        `[Read the full article](${postUrl})`,
      ].filter((line) => line !== null).join('\n'),
      image_alt: `${title} image`,
      matrix_request_id: requestIdFor(postId),
    },
  }];
});
